survey.calculation:
if (${s_ari_have_cough}='yes', 
  concat (
    'Cough', 
      concat (
        ' that began: ', 
        jr:choice-name(${s_when_illness}, '${s_when_illness}')
      )
    ),
  ''
)

if(${diff_assess_date_report_date} < 7,
    format-date-time(date-time(decimal-date-time(${assessment_date})+ 7),"%d/%m/%Y"),
    if(${diff_assess_date_report_date} = 7, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
     if(${diff_assess_date_report_date} > 7 and ${diff_assess_date_report_date} < 14 ,
      format-date-time(date-time(decimal-date-time(${assessment_date})+ 14),"%d/%m/%Y"),
        if(${diff_assess_date_report_date} = 14, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
         if(${diff_assess_date_report_date} > 14 and ${diff_assess_date_report_date} < 21,
            format-date-time(date-time(decimal-date-time(${assessment_date})+ 21),"%d/%m/%Y"),
            if(${diff_assess_date_report_date} = 21, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
             if(${diff_assess_date_report_date} > 21 and ${diff_assess_date_report_date} < 28 ,
                format-date-time(date-time(decimal-date-time(${assessment_date})+ 28),"%d/%m/%Y"),
               if(${diff_assess_date_report_date} = 28, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
                  if(${diff_assess_date_report_date} > 28 and ${diff_assess_date_report_date} < 42 ,
                    format-date-time(date-time(decimal-date-time(${assessment_date})+ 42),"%d/%m/%Y"),
                   if(${diff_assess_date_report_date} = 42, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
                     if(${diff_assess_date_report_date} > 42 and ${diff_assess_date_report_date} < 56 ,
                        format-date-time(date-time(decimal-date-time(${assessment_date})+ 56),"%d/%m/%Y"),
                        if(${diff_assess_date_report_date} = 56, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
                         if(${diff_assess_date_report_date} > 56 and ${diff_assess_date_report_date} < 70,
                            format-date-time(date-time(decimal-date-time(${assessment_date})+ 70),"%d/%m/%Y"),
                            if(${diff_assess_date_report_date} = 70, format-date-time(decimal-date-time(now()),"%d/%m/%Y"),
                             if(${diff_assess_date_report_date} > 70 and ${diff_assess_date_report_date} < 84,
                                format-date-time(date-time(decimal-date-time(${assessment_date})+ 84),"%d/%m/%Y"),
                                format-date-time(decimal-date-time(now()),"%d/%m/%Y")
                             )
                           )
                         )
                       )
                     )
                   )
                 )
                )
               )
            )
          )
        )
      )
    )
 )

if( number(${drugs_proposed}) = number(${drugs_not_given_out_of_stock}) or number(${drugs_proposed}) = number(${drugs_given})  ,
     'false'   
, 
    if( ${new_CAT} = '' ,
         'true'   
    , 
         'false'
    )
)

if( ${patient_age_in_months}<12,'',
    if(${patient_age_in_months}<24,
        if (${s_give_albendazole_type} ='200_mg_albendazole',
                if(${language} = ‘en’,'1 tablet of 200mg', if (${language} = ‘fr’,'1 comprimé de 200 mg', '200 mg furakisɛ 1'))
            ,
                if(${language} = ‘en’,'½  tablet of 400mg', if (${language} = ‘fr’,'½ comprimé de 400 mg', '400 mg furakisɛ ½'))
            )
        ,

        if (${s_give_albendazole_type} ='200_mg_albendazole',
                if(${language} = ‘en’,'2 tablets of 200mg', if (${language} = ‘fr’,'2 comprimés de 200 mg', '200 mg furakisɛ 2'))
            ,
                if(${language} = ‘en’,'1 tablet of 400mg', if (${language} = ‘fr’,'1 comprimé de 400 mg', '400 mg furakisɛ 1'))
        )

    )
)

if (${s_give_paracetamol_dosage}='quarter_tab_paracetamol_once',(1 div 4),
        if (${s_give_paracetamol_dosage}='half_tab_paracetamol_once',(1 div 2),
            if (${s_give_paracetamol_dosage} ='quarter_tab_paracetamol_3x_a_day',((1 div 4) *3),
                if (${s_give_paracetamol_dosage} ='half_tab_paracetamol_3x_a_day', ((1 div 2) *3), 0)
            )
        )
    )
